using namespace astro;
void wait(app::DeepSkyController& c){QElapsedTimer t;t.start();while(c.busy()&&t.elapsed()<20000){QCoreApplication::processEvents();QThread::msleep(1);}ASTRO_TEST_CHECK(!c.busy());}
QVariantMap group(const QVariantMap& plan,const QString& role,double exposure=0){for(const auto& v:plan["groups"].toList()){const auto r=v.toMap();if(r["role"]==role&&(!exposure||r["exposure"].toDouble()==exposure))return r;}return {};}
QVariantList ids(const QVariantMap& plan){QVariantList out;for(const auto& v:plan["groups"].toList())if(!v.toMap()["blocked"].toBool())out<<v.toMap()["id"];return out;}
int main(int argc,char** argv){
 QGuiApplication application(argc,argv);QTemporaryDir d;QCoreApplication::setOrganizationName("AstroTest");QCoreApplication::setApplicationName("BatchMasters");QSettings::setDefaultFormat(QSettings::IniFormat);QSettings::setPath(QSettings::IniFormat,QSettings::UserScope,d.path());QSettings().setValue("calibration/libraryDirectory",d.filePath("masters"));
 recording::AstroImage a;a.width=a.height=64;a.channels=1;a.bits=32;a.camera="Controlled sensor";a.binX=a.binY=1;a.hasGain=a.hasOffset=a.hasTemperature=true;a.gain=100;a.offset=10;a.temperature=-10;a.exposure=30;a.filter="L";a.samples.assign(4096,.1f);
 auto write=[&](QString name,float base,float slope=0,bool cosmic=false){auto image=a;for(int y=0;y<64;++y)for(int x=0;x<64;++x)image.samples[y*64+x]=base+slope*x/63;if(cosmic)image.samples[50]=100;const auto path=d.filePath(name+".fits");recording::writeAstroFits(path.toStdString(),image);return QUrl::fromLocalFile(path);};
 app::DeepSkyController c;c.addFiles({write("light",.6f,.2f)},"Light");wait(c);c.integrate(true,0,false,false);wait(c);const auto previous=c.sessionSnapshot().images["linear"];ASTRO_TEST_CHECK(previous);
 c.addFiles({write("dark30a",.04f),write("dark30b",.04f),write("dark30cosmic",.04f,0,true)},"Dark");wait(c);a.exposure=60;c.addFiles({write("dark60a",.08f),write("dark60b",.08f)},"Dark");wait(c);
 qInfo()<<"phase darks";auto plan=c.calibrationBatchPlan();ASTRO_TEST_CHECK(plan["groups"].toList().size()==2&&group(plan,"Dark",30)["count"]==3&&group(plan,"Dark",60)["count"]==2);const auto frames=c.frames();
 c.createCalibrationMasters(ids(plan),{},"Session",false,plan["revision"].toString());wait(c);ASTRO_TEST_CHECK(c.calibrationMasters().size()==2&&c.frames()==frames&&c.sessionSnapshot().images["linear"]==previous);ASTRO_TEST_CHECK(c.calibrationBatchResults().size()==2);
 for(const auto& v:c.calibrationMasters()){const auto master=v.toMap();auto image=recording::readAstroImage(master["path"].toString().toStdString());ASTRO_TEST_CHECK(master["sourceHashes"].toList().size()==master["masterCount"]);if(image.exposure==30){ASTRO_TEST_CHECK(std::abs(image.samples[50]-.04f)<1e-7&&image.masterRejected==1&&master["compatibility"]==0);}else ASTRO_TEST_CHECK(master["compatibility"]==2&&std::abs(image.samples[0]-.08f)<1e-7);}
 qInfo()<<"phase splitting";
 // Strict configuration splitting prevents chained tolerance grouping and unknown/known merges.
 auto split=frames[1].toMap();QVariantList variants;split["selected"]=true;for(int n=0;n<6;++n){auto row=split;if(n==1)row["temperature"]=-9.9;if(n==2)row["gain"]=101;if(n==3)row.remove("gain");if(n==4)row["binX"]=2;if(n==5)row["aduScale"]=65535;variants<<row;}
 ASTRO_TEST_CHECK(app::calibrationBatchPlan(variants)["groups"].toList().size()==6);
 qInfo()<<"phase flats";
 // A flat uses the unique matching dark-flat before a bias; sources are normalized once.
 app::DeepSkyController flats;a.exposure=.01;flats.addFiles({write("bias",.02f)},"Bias");wait(flats);a.exposure=2;flats.addFiles({write("df2",.03f)},"DarkFlat");wait(flats);flats.addFiles({write("flatL1",.53f,.4f),write("flatL2",.63f,.48f)},"Flat");wait(flats);
 plan=flats.calibrationBatchPlan();auto flat=group(plan,"Flat");auto df=group(plan,"DarkFlat");ASTRO_TEST_CHECK(flat["defaultCorrection"]==df["id"]&&flat["corrections"].toList().size()==2);
 flats.createCalibrationMasters({flat["id"]},{},"Flat",false,plan["revision"].toString());wait(flats);qInfo()<<flats.status()<<flats.calibrationBatchResults();ASTRO_TEST_CHECK(!flats.calibrationBatchResults().empty());ASTRO_TEST_CHECK(flats.calibrationBatchResults().front().toMap()["state"]=="saved");auto flatMaster=app::calibrationMasterInventory().back().toMap();auto normalized=recording::readAstroImage(flatMaster["path"].toString().toStdString());ASTRO_TEST_CHECK(normalized.normalizedMasterFlat&&flatMaster["correctionHashes"].toList().size()==1);
 auto expected=processing::masterFrame(2,[&](int n){auto image=recording::readAstroImage(flats.frames()[n+2].toMap()["path"].toString().toStdString());for(auto& v:image.samples)v-=.03f;return image;},true,{},true);ASTRO_TEST_CHECK(expected.samples==normalized.samples);
 qInfo()<<"phase ambiguity";
 // Another thermally compatible configuration requires a deliberate choice.
 a.temperature=-9;flats.addFiles({write("df2other",.035f)},"DarkFlat");wait(flats);plan=flats.calibrationBatchPlan();flat=group(plan,"Flat");ASTRO_TEST_CHECK(flat["defaultCorrection"].toString().isEmpty());const auto before=app::calibrationMasterInventory().size();flats.createCalibrationMasters({flat["id"]},{},"",false,plan["revision"].toString());wait(flats);ASTRO_TEST_CHECK(app::calibrationMasterInventory().size()==before);
 df=group(plan,"DarkFlat");flats.createCalibrationMasters({flat["id"]},{{flat["id"].toString(),df["id"]}},"Chosen",false,plan["revision"].toString());wait(flats);ASTRO_TEST_CHECK(app::calibrationMasterInventory().size()==before+1);
 qInfo()<<"phase missing";
 // Unknown metadata requires an explicit review and leaves a provenance flag.
 app::DeepSkyController unknown;a.camera="";a.hasGain=false;a.exposure=45;unknown.addFiles({write("unknown",.05f)},"Dark");wait(unknown);plan=unknown.calibrationBatchPlan();ASTRO_TEST_CHECK(group(plan,"Dark")["reviewRequired"].toBool());const auto size=app::calibrationMasterInventory().size();unknown.createCalibrationMasters(ids(plan),{},"",false,plan["revision"].toString());wait(unknown);ASTRO_TEST_CHECK(app::calibrationMasterInventory().size()==size);unknown.createCalibrationMasters(ids(plan),{},"Reviewed",true,plan["revision"].toString());wait(unknown);ASTRO_TEST_CHECK(app::calibrationMasterInventory().back().toMap()["metadataReviewed"].toBool());
 qInfo()<<"phase stale";
 // Stale plans and known bad corrections cannot be overridden by review.
 const auto stale=plan;unknown.setSelected(0,false);unknown.createCalibrationMasters(ids(stale),{},"",true,stale["revision"].toString());wait(unknown);ASTRO_TEST_CHECK(app::calibrationMasterInventory().size()==size+1);
 auto bad=df;bad["exposure"]=99;ASTRO_TEST_CHECK(app::calibrationCorrectionCompatibility(bad,flat)["compatibility"]==2);
 qInfo()<<"phase partial";
 // A changed file stops the batch after the first atomic publication; reports cover unfinished jobs.
 app::DeepSkyController partial;a.camera="Controlled sensor";a.hasGain=true;a.temperature=-10;a.exposure=.01;partial.addFiles({write("partial-bias",.02f)},"Bias");wait(partial);a.exposure=30;const auto changed=write("changed",.04f);partial.addFiles({changed},"Dark");wait(partial);a.exposure=60;partial.addFiles({write("pending",.08f)},"Dark");wait(partial);plan=partial.calibrationBatchPlan();QFile file(changed.toLocalFile());ASTRO_TEST_CHECK(file.open(QIODevice::Append));file.write("changed after import");file.close();const auto count=app::calibrationMasterInventory().size();bool succeeded=true;QObject::connect(&partial,&app::DeepSkyController::operationFinished,[&](bool success,const QString&){succeeded=success;});partial.createCalibrationMasters(ids(plan),{},"Partial",false,plan["revision"].toString());wait(partial);ASTRO_TEST_CHECK(!succeeded&&app::calibrationMasterInventory().size()==count+1);const auto report=partial.calibrationBatchResults();ASTRO_TEST_CHECK(report.size()==3&&report[0].toMap()["state"]=="saved"&&report[1].toMap()["state"]=="failed"&&report[2].toMap()["state"]=="pending");
 qInfo()<<"phase cancel";
 // Cancellation before work preserves the library and reports cancellation.
 app::DeepSkyController cancel;a.exposure=120;cancel.addFiles({write("cancel",.1f)},"Dark");wait(cancel);plan=cancel.calibrationBatchPlan();const auto inventorySize=app::calibrationMasterInventory().size();cancel.createCalibrationMasters(ids(plan),{},"Cancel",false,plan["revision"].toString());cancel.cancel();wait(cancel);qInfo()<<cancel.status()<<cancel.calibrationBatchResults();ASTRO_TEST_CHECK(!cancel.calibrationBatchResults().empty());ASTRO_TEST_CHECK(app::calibrationMasterInventory().size()==inventorySize&&cancel.calibrationBatchResults().front().toMap()["state"]=="cancelled");
 std::stop_source stopped;stopped.request_stop();bool refused=false;try{app::buildCalibrationBatchMaster(group(plan,"Dark"),{},[&](const QVariantMap&){return a;},stopped.get_token(),{});}catch(const std::exception&){refused=true;}ASTRO_TEST_CHECK(refused);
 // AC_ORIG remains metadata for normalized Float32 data, including imported masters.
 a.originalScale=65535;a.exposure=30;app::DeepSkyController units;units.addFiles({write("unit-light",.5f)},"Light");wait(units);auto unitDark=a;unitDark.samples.assign(4096,.04f);unitDark.masterRole="Dark";unitDark.masterCount=1;const auto unitEntry=app::storeCalibrationMaster(unitDark,"Normalization units",{});units.addFiles({QUrl::fromLocalFile(unitEntry["path"].toString())},"Auto");wait(units);ASTRO_TEST_CHECK(units.frames().front().toMap()["aduScale"]==65535&&units.frames().back().toMap()["aduScale"]==65535&&app::masterCompatibility(unitEntry,units.frames())["compatibility"]==0);auto wrongUnits=units.frames();auto wrongRow=wrongUnits.front().toMap();wrongRow["aduScale"]=1;wrongUnits[0]=wrongRow;ASTRO_TEST_CHECK(app::masterCompatibility(unitEntry,wrongUnits)["compatibility"]==2);
 // A selected saved bias is a checked correction, never a new raw master group.
 a.originalScale=1;a.exposure=2;app::DeepSkyController savedCorrection;QVariantMap savedBias;for(const auto& v:app::calibrationMasterInventory())if(v.toMap()["role"]=="Bias")savedBias=v.toMap();ASTRO_TEST_CHECK(!savedBias.empty());savedCorrection.addFiles({QUrl::fromLocalFile(savedBias["path"].toString())},"Auto");wait(savedCorrection);savedCorrection.addFiles({write("saved-correction-flat",.52f,.3f)},"Flat");wait(savedCorrection);plan=savedCorrection.calibrationBatchPlan();flat=group(plan,"Flat");ASTRO_TEST_CHECK(plan["ignoredMasters"]==1&&plan["groups"].toList().size()==1&&flat["defaultCorrection"].toString().startsWith("selected:"));savedCorrection.createCalibrationMasters({flat["id"]},{},"Saved correction",false,plan["revision"].toString());wait(savedCorrection);ASTRO_TEST_CHECK(savedCorrection.calibrationBatchResults().front().toMap()["state"]=="saved");const auto provenance=app::calibrationMasterInventory().back().toMap();ASTRO_TEST_CHECK(provenance["correctionHashes"].toList()==QVariantList{savedBias["hash"]});
 QSettings().setValue("application/integrationTemporaryDirectory",d.filePath("missing"));plan=c.calibrationBatchPlan();for(const auto& v:plan["groups"].toList())ASTRO_TEST_CHECK(v.toMap()["blocked"].toBool());c.chooseIntegrationTemporaryDirectory({});
 // A library bias can correct selected flats without being selected as a light calibration.
 app::DeepSkyController libraryCorrection;a.exposure=2;libraryCorrection.addFiles({write("library-correction-flat",.6f,.2f)},"Flat");wait(libraryCorrection);plan=libraryCorrection.calibrationBatchPlan();flat=group(plan,"Flat");ASTRO_TEST_CHECK(flat["defaultCorrection"].toString().startsWith("library:"));libraryCorrection.createCalibrationMasters({flat["id"]},{},"Library correction",false,plan["revision"].toString());wait(libraryCorrection);ASTRO_TEST_CHECK(!libraryCorrection.calibrationBatchResults().empty()&&libraryCorrection.calibrationBatchResults().front().toMap()["state"]=="saved");
 QFile brokenLibrary(d.filePath("masters/library.json"));ASTRO_TEST_CHECK(brokenLibrary.open(QIODevice::WriteOnly));brokenLibrary.write("invalid index");brokenLibrary.close();plan=c.calibrationBatchPlan();ASTRO_TEST_CHECK(!plan["libraryError"].toString().isEmpty());for(const auto& v:plan["groups"].toList())ASTRO_TEST_CHECK(v.toMap()["blocked"].toBool());
 ASTRO_TEST_CHECK(c.sessionSnapshot().images["linear"]==previous);
}
